import { useMemo } from 'react';
import { useProfile } from '@/context/ProfileContext';
import { styleById, PARTICLES } from '@/data/styles';
import './scenery.css';

/**
 * Everything behind the glass.
 *
 * The base layer is a real PNG wallpaper generated by
 * `npm run assets`; on top of it sit the aurora fields, the
 * caustics, the particle weather (bubbles, leaves, snow, embers
 * or sparkles — also PNGs) and the drifting lens flares.
 *
 * Which layers run, how dense they are and how far the wallpaper
 * is dimmed are all member preferences.
 */
export function Scenery() {
  const { profile } = useProfile();
  const t = profile.theme;
  const style = styleById(t.style);
  const spec = PARTICLES[t.particle];

  const particles = useMemo(() => {
    if (!spec || t.particle === 'none') return [];
    const [minSize, maxSize] = spec.size;
    return Array.from({ length: t.particleCount }, (_, i) => {
      // deterministic per index so the field does not reshuffle on re-render
      const r = (n) => ((Math.sin(i * 12.9898 + n * 78.233) * 43758.5453) % 1 + 1) % 1;
      const size = minSize + r(1) * (maxSize - minSize);
      return {
        key: i,
        style: {
          left: `${(r(2) * 108 - 4).toFixed(2)}%`,
          width: `${size.toFixed(1)}px`,
          height: `${size.toFixed(1)}px`,
          backgroundImage: `url(${spec.png})`,
          '--drift': `${((r(3) - 0.5) * spec.drift).toFixed(0)}px`,
          '--spin': spec.spin ? `${(r(7) > 0.5 ? 1 : -1) * (180 + r(8) * 540)}deg` : '0deg',
          '--peak': (0.3 + r(4) * 0.6).toFixed(2),
          animationDuration: `${(spec.rise ? 15 : 11) + r(5) * 26}s`,
          animationDelay: `${(-r(6) * 40).toFixed(1)}s`,
        },
      };
    });
  }, [spec, t.particle, t.particleCount]);

  return (
    <div className="scenery" aria-hidden="true">
      {t.wallpaper && (
        <div
          className="scenery-photo"
          style={{
            backgroundImage: `url(${style.bg})`,
            filter: t.wallpaperBlur ? `blur(${t.wallpaperBlur}px)` : undefined,
            transform: t.wallpaperBlur ? 'scale(1.06)' : undefined,
          }}
        />
      )}
      <div className="scenery-base" style={{ opacity: t.wallpaper ? t.wallpaperDim : 1 }} />

      {t.aurora && (
        <>
          <div className="aurora aurora-a" />
          <div className="aurora aurora-b" />
          <div className="aurora aurora-c" />
        </>
      )}

      {t.caustics && <div className="caustics" />}

      <div className={`particles particles-${t.particle}`}>
        {particles.map((p) => <span key={p.key} className="particle" style={p.style} />)}
      </div>

      {t.flares && (
        <>
          <div className="flare flare-1" />
          <div className="flare flare-2" />
        </>
      )}

      <div className="vignette" />
      {t.scanlines && <div className="scanlines" />}
    </div>
  );
}
